const xcry_hash_vector_t *vp;
cry_operation_t op;
cry_algorithm_t alg;
uint8_t digest[XCRY_DIGEST_MAX];
size_t len;
unsigned i;
msg_t msg;

code.value:
alg = CRY_ALG_NONE;
for (i = 0U; i < XCRY_SHA_VECTORS_COUNT; i++) {
  cry_capabilities_t caps;

  if (cryGetCapabilities(XCRY_DRIVER, xcry_sha_vectors[i].algorithm,
                         &caps) == HAL_RET_SUCCESS) {
    alg = xcry_sha_vectors[i].algorithm;
    /* The "abc" example follows the empty message.*/
    vp = &xcry_sha_vectors[i + 1U];
    break;
  }
}
if (alg == CRY_ALG_NONE) {
  test_println("--- Skipped, no hash supported by the driver");
  return;
}

msg = cryHashBegin(XCRY_DRIVER, &op, alg);
test_assert(msg == HAL_RET_SUCCESS, "begin failed");
msg = cryHashUpdate(&op, vp->size, vp->msg);
test_assert(msg == HAL_RET_SUCCESS, "update failed");
cryOperationAbort(&op);
cryOperationAbort(&op);
msg = cryHashBegin(XCRY_DRIVER, &op, alg);
test_assert(msg == HAL_RET_SUCCESS, "begin after abort failed");
msg = cryHashUpdate(&op, vp->size, vp->msg);
test_assert(msg == HAL_RET_SUCCESS, "update failed");
msg = cryHashFinal(&op, sizeof digest, digest, &len);
test_assert(msg == HAL_RET_SUCCESS, "final failed");
test_assert(memcmp(digest, vp->digest, vp->digest_size) == 0,
            "digest mismatch");
cryOperationAbort(&op);

local_variables.value:
static const uint8_t key[16] = {0};
static const uint8_t iv[16] = {0};
cry_cipher_params_t cparams = {iv, sizeof iv};
cry_aead_params_t aparams = {iv, 12U, 16U, 0U, 0U};
cry_capabilities_t caps;
cry_operation_t op;
cry_algorithm_t alg;
msg_t msg;

code.value:
for (alg = CRY_ALG_AES_ECB; alg <= CRY_ALG_SHA512; alg++) {
  if (cryGetCapabilities(XCRY_DRIVER, alg, &caps) == HAL_RET_SUCCESS) {
    continue;
  }
  switch (alg) {
  case CRY_ALG_AES_ECB:
    cparams.iv = NULL;
    cparams.iv_size = 0U;
    msg = cryCipherBegin(XCRY_DRIVER, &op, CRY_KEY_TRANSIENT, alg,
                         CRY_ENCRYPT, &cparams);
    cparams.iv = iv;
    cparams.iv_size = sizeof iv;
    break;
  case CRY_ALG_AES_CBC:
  case CRY_ALG_AES_CFB128:
  case CRY_ALG_AES_CTR:
    msg = cryCipherBegin(XCRY_DRIVER, &op, CRY_KEY_TRANSIENT, alg,
                         CRY_ENCRYPT, &cparams);
    break;
  case CRY_ALG_AES_GCM:
  case CRY_ALG_AES_CCM:
    msg = cryAeadBegin(XCRY_DRIVER, &op, CRY_KEY_TRANSIENT, alg,
                       CRY_ENCRYPT, &aparams);
    break;
  case CRY_ALG_AES_CMAC:
  case CRY_ALG_HMAC_SHA256:
  case CRY_ALG_HMAC_SHA384:
  case CRY_ALG_HMAC_SHA512:
    msg = cryMacBegin(XCRY_DRIVER, &op, CRY_KEY_TRANSIENT, alg,
                      false, 16U);
    break;
  default:
    msg = cryHashBegin(XCRY_DRIVER, &op, alg);
    break;
  }
  test_assert(msg == CRY_ERR_UNSUPPORTED, "unsupported algorithm began");
  cryOperationAbort(&op);
}

if (xcry_unsupported(CRY_ALG_AES_ECB)) {
  return;
}

for (i = 0U; i < XCRY_AES_ECB_VECTORS_COUNT; i++) {
  const xcry_cipher_vector_t *vp = &xcry_aes_ecb_vectors[i];

  if (!xcry_key_supported(vp->algorithm, vp->key_size)) {
    continue;
  }
  msg = xcry_cipher(vp, CRY_ENCRYPT, vp->pt, xcry_out, vp->size);
  test_assert(msg == HAL_RET_SUCCESS, "encryption failed");
  test_assert(memcmp(xcry_out, vp->ct, vp->size) == 0,
              "ciphertext mismatch");
}

for (i = 0U; i < XCRY_AES_ECB_VECTORS_COUNT; i++) {
  const xcry_cipher_vector_t *vp = &xcry_aes_ecb_vectors[i];

  if (!xcry_key_supported(vp->algorithm, vp->key_size)) {
    continue;
  }
  msg = xcry_cipher(vp, CRY_DECRYPT, vp->ct, xcry_out, vp->size);
  test_assert(msg == HAL_RET_SUCCESS, "decryption failed");
  test_assert(memcmp(xcry_out, vp->pt, vp->size) == 0,
              "plaintext mismatch");
}

if (xcry_unsupported(CRY_ALG_AES_ECB)) {
  return;
}

for (i = 0U; i < XCRY_AES_ECB_VECTORS_COUNT; i++) {
  const xcry_cipher_vector_t *vp = &xcry_aes_ecb_vectors[i];

  if (!xcry_key_supported(vp->algorithm, vp->key_size)) {
    continue;
  }
  msg = xcry_cipher(vp, CRY_ENCRYPT, vp->pt, xcry_out, 5U);
  test_assert(msg == HAL_RET_SUCCESS, "encryption failed");
  test_assert(memcmp(xcry_out, vp->ct, vp->size) == 0,
              "ciphertext mismatch");
}

for (i = 0U; i < XCRY_AES_ECB_VECTORS_COUNT; i++) {
  const xcry_cipher_vector_t *vp = &xcry_aes_ecb_vectors[i];

  if (!xcry_key_supported(vp->algorithm, vp->key_size)) {
    continue;
  }
  msg = xcry_cipher(vp, CRY_DECRYPT, vp->ct, xcry_out, 1U);
  test_assert(msg == HAL_RET_SUCCESS, "decryption failed");
  test_assert(memcmp(xcry_out, vp->pt, vp->size) == 0,
              "plaintext mismatch");
}

if (xcry_unsupported(CRY_ALG_AES_ECB)) {
  return;
}

memcpy(xcry_in, vp->pt, vp->size);
msg = xcry_cipher(vp, CRY_ENCRYPT, xcry_in, xcry_out, vp->size);
test_assert(msg == HAL_RET_SUCCESS, "encryption failed");
test_assert(memcmp(xcry_out, vp->ct, vp->size) == 0,
            "ciphertext mismatch");

memcpy(xcry_in, vp->ct, vp->size);
msg = xcry_cipher(vp, CRY_DECRYPT, xcry_in, xcry_out, 1000U);
test_assert(msg == HAL_RET_SUCCESS, "decryption failed");
test_assert(memcmp(xcry_out, vp->pt, vp->size) == 0,
            "plaintext mismatch");

if (xcry_unsupported(CRY_ALG_AES_CBC)) {
  return;
}

for (i = 0U; i < XCRY_AES_CBC_VECTORS_COUNT; i++) {
  const xcry_cipher_vector_t *vp = &xcry_aes_cbc_vectors[i];

  if (!xcry_key_supported(vp->algorithm, vp->key_size)) {
    continue;
  }
  msg = xcry_cipher(vp, CRY_ENCRYPT, vp->pt, xcry_out, vp->size);
  test_assert(msg == HAL_RET_SUCCESS, "encryption failed");
  test_assert(memcmp(xcry_out, vp->ct, vp->size) == 0,
              "ciphertext mismatch");
}

for (i = 0U; i < XCRY_AES_CBC_VECTORS_COUNT; i++) {
  const xcry_cipher_vector_t *vp = &xcry_aes_cbc_vectors[i];

  if (!xcry_key_supported(vp->algorithm, vp->key_size)) {
